55474437bf15d51a:
#definition([مثال محلول: حد مشروط لأخذ العينات], [
  مع نسبة سيئة ثابتة ⟦0⟧ و⟦1⟧ فتحة مستقلة، يكون احتمال تفويت كل موضع سيئ ⟦2⟧. ومع 32 فتحة يبلغ نحو 0.034. تفترض المقدمة تثبيت الالتزام قبل اختيار العينات. إذا استطاع المُثبت تجربة جذور كثيرة، أو اختيار الالتزام الذي يكشفه، أو ربط حالات الفشل، فلا يحسب هذا التعبير تلك الاستراتيجية.
])

e51753f477a22a66:
#objectives([
  اشرح لماذا تكون دالة شبه عشوائية ذات مفتاح هي الأداة المناسبة عندما ينتمي المُصدر والمتحقق إلى مجال الثقة نفسه. وحدد حد تزوير وسم من 128 بت، وصف سجل التحدي عديم الحالة وحد مجموعة المستهلك، واقرأ جدول اشتقاق المفاتيح.
])

045072c80151f3ea:
#callout([اللمّة 3: حد التزوير], [
  عند نمذجة BLAKE3 في الوضع ذي المفتاح بوصفه PRF واستخدام وسم من 16 بايت، يزور خصم يجري ⟦0⟧ استعلام تحقق رمزًا صالحًا باحتمال لا يتجاوز ⟦1⟧. عند مليون استعلام في الثانية يكون ذلك ⟦2⟧ في الثانية.
])

3d3ab8947b56bf17:
#callout([اللمّة 4: تنمو الحالة فقط مع العمل المدفوع], [
  لتكن ⟦0⟧ مجموعة وسوم التحديات التي يتذكرها البرنامج. لا يدخل وسم إلى ⟦1⟧ إلا بعد قبول إثبات صالح له، ويخرج بعد مدة صلاحية التحدي. لذا ⟦2⟧ عندما تحد ⟦3⟧ معدل الحلول المميزة المقبولة خلال تلك الفترة. لا يُخصص وسم عند جلب تحدٍّ مجانًا. للتنفيذ سعة ثابتة أيضًا، وقد يرفض حلًا صالحًا عند الامتلاء. هذا حد للحالة، وليس حدًا أدنى لكل استراتيجية حسابية لدى خصم.
])

